(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.025-t*0.15)*8+Math.cos(my*0.02+t*0.25)*6;
  const w2y = Math.cos(my*0.022+t*0.18)*8+Math.sin(mx*0.019-t*0.22)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,4],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,5],
    [60+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65)*50,0.11,2.1,0.5],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+1)*40,0.085,1.8,1.5]
  ];
  let aS=0,iS=0,iS2=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph*0.5);
    iS2+=Math.sin(d*f*1.3-t*sp*0.4+2.8+ph*0.3);
  }
  const act=aS/8,inh=iS/8,inh2=iS2/8;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3=Math.sin(sx*0.08-t*1.5)*Math.cos(sy*0.06+t*1.2)*0.15;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const pulse=Math.sin(dist*0.08-t*3)*0.15*Math.exp(-dist*0.005);
  const moire=Math.sin(sx*0.1)*Math.sin(sy*0.1)*Math.sin((sx-sy)*0.07+t)*0.3;
  const reaction=Math.tanh((act-inh*0.5-inh2*0.3+bg*0.3+spiral+pulse+moire)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2=Math.sin(sx*0.08+sy*0.06-t*0.5)*Math.sin(sx*0.05-sy*0.09+t*0.7)*0.15;
  const blend=reaction*0.6+cell*0.2+cell2*0.2;
  const hueShift=Math.sin(t*0.15)*0.5+0.5;
  const v=Math.max(0,Math.min(1,blend*0.5+0.5+hueShift*0.03));
  const pal=[[5,12,52],[10,45,95],[18,85,125],[25,140,135],[50,175,120],[140,190,75],[210,185,55],[225,145,60],[215,100,65],[185,60,70],[130,40,75],[70,25,65],[30,15,55],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2+Math.abs(cell2)*0.1;
  const edge=Math.abs(reaction)>0.7?1.2:1.0;
  const glow=Math.exp(-Math.abs(reaction)*2)*0.15+1.0;
  const m=lum*edge*glow;
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0];
}
